# Compute per-text mean MLP-input activations for thinking / answer / wait positions, per layer
import numpy as np, json
meta = json.load(open('/work/fwd_3/meta.json'))
lengths = meta['lengths']; tids = meta['token_ids']
C = 10
masks = []  # per text: dict of position arrays
first_close = []
for i in range(C):
    t = tids[i][:lengths[i]]
    try:
        idx_close = t.index(248069)
    except ValueError:
        idx_close = lengths[i]
    first_close.append(idx_close)
    pos = np.arange(lengths[i])
    think_pos = pos[pos < idx_close]
    ans_pos = pos[pos >= idx_close]
    wait_pos = np.array([p for p in range(lengths[i]-1) if t[p+1]==13784])  # predict Wait
    masks.append((think_pos, ans_pos, wait_pos))
print('first_close per text:', first_close)
sum_think = {L: np.zeros(3584, dtype=np.float64) for L in range(24)}
sum_ans = {L: np.zeros(3584, dtype=np.float64) for L in range(24)}
sum_wait = {L: np.zeros(3584, dtype=np.float64) for L in range(24)}
cnt_think = cnt_ans = cnt_wait = 0
for i in range(C):
    for L in range(24):
        a = np.load(f'/work/fwd_3/mlp_act_L{L}.npy')[i].astype(np.float32)
        n = lengths[i]
        tp, ap, wp = masks[i]
        sum_think[L] += a[tp].sum(0); sum_ans[L] += a[ap].sum(0)
        if len(wp): sum_wait[L] += a[wp].sum(0)
    cnt_think += len(tp); cnt_ans += len(ap); cnt_wait += len(wp)
print('counts: think', cnt_think, 'answer', cnt_ans, 'wait', cnt_wait)
means_think = {L: sum_think[L]/cnt_think for L in range(24)}
means_ans = {L: sum_ans[L]/cnt_ans for L in range(24)}
means_wait = {L: sum_wait[L]/max(cnt_wait,1) for L in range(24)}
np.save('/work/means_think.npy', np.stack([means_think[L] for L in range(24)]))
np.save('/work/means_ans.npy', np.stack([means_ans[L] for L in range(24)]))
np.save('/work/means_wait.npy', np.stack([means_wait[L] for L in range(24)]))

